less(A[i].key, A[j].key)
void selection_sort(int A[], int l, int r)
{ 
int i, j, min;
for (i = l; i < r; i++) {
min = i;
for (j = i+1; j <= r; j++) {
if (A[j] < A[min]) min = j;
}
exchange(A[i], A[min]); // vertauschen 
}
}
