void insertion_sort(int A[], int l, int r)
{ 
int i, j, v;
for (i = l+1; i <= r; i++) {
v = A[i];
for (j = i-1; j >= l; j--) {
if (v < A[j]) A[j+1] = A[j];
else break; 
}
A[j+1] = v;
}
}
