Datenstruktur
void visit(T* item)
{ // Verarbeitung von item
}
void preorder(btreeptr b)
{
if (b == NULL) return;
visit(b->data);
preorder(b->left);
preorder(b->right);
}
void inorder(btreeptr b)
{
if (b == NULL) return;
inorder(b->left);
visit(b->data);
inorder(b->right);
}
void postorder(btreeptr b)
{
if (b == NULL) return;
postorder(b->left);
postorder(b->right);
visit(b->data);
}
